section.arch:state-shape:
GameSession { schemaVersion : number // 마이그레이션용 puzzleId : string // givens 문자열의 해시. 세션 동일성 판정 키 dim : 9 // spec.py가 12/16도 지원하나 UI는 9만 대응 givens : Uint8Array(81) // 0 = 빈칸 solution : Uint8Array(81) // 확인 버튼용. 자체 세션에만 존재. URL에는 넣지 않는다(섹션 15) // 공유 링크로 들어온 세션은 solution=null. 확인은 제약 검사로 대체 values : Uint8Array(81) // 사용자 확정값 candidates : Uint16Array(81) // 비트마스크. 값 n은 1 shl (n-1) cellNotes : Record<cellIndex, string> regionNotes : Record<regionKey, string> // regionKey = "r0".."r8" | "c0".."c8" | "b0".."b8" createdAt : number updatedAt : number }
UiState (비영속) { selection : number | null // 셀 인덱스 0..80 activeDigit : number | null // 모바일 Digit First candidateHeld : boolean // Shift 준모드. 데스크톱 전용 candidateSticky : boolean // Space 토글 / 모바일 연필 토글. 두 경로가 같은 플래그를 쓴다 editor : null | { target: {kind:"cell"|"region", key:string}, draft:string } dialog : null | { kind:"conflict"|"confirm"|"help"|"share", payload:object } railOpen : boolean boardScale : number // 1.0 또는 편집 중 계산값 } // inputAdapter 필드는 삭제되었다. 어댑터가 가산이라 "현재 어댑터"라는 상태가 존재하지 않는다(AD1~AD3).
Settings (영속, localStorage sudoku:v1:settings) { schemaVersion : number autoRemoveCandidates : boolean // CF4. 기본 true showConflicts : boolean // CF1. 기본 true shiftQuasimode : boolean // 기본 true. AZERTY 사용자가 끌 수 있다 numberBarCollapsed : boolean // AD3. 기본 false hintStripSeenCount : number // ST0 힌트 스트립 3회 노출 정책 }
HistoryEntry { kind : "value" | "candidates" | "cellNote" | "regionNote" key : number | string before : number | string after : number | string groupId: number | null // 자동 후보 제거를 한 건으로 묶는 식별자 at : number }
candidates를 비트마스크로 두면 후보 토글이 XOR 1회이고 localStorage 직렬화도 짧다. Uint8Array/Uint16Array는 JSON 직렬화 시 배열 또는 base64 문자열로 변환한다.
